(function(){window.PhysicaRankPyqNeet_chemistry_coordinationcompounds=[{id:"neet-2026r-q053",pn:53,y:"Re-NEET 2026 \xB7 21 Jun",tp:"Coordination Compounds",st:"Crystal field spectrochemical series",q:"According to crystal field theory, the correct order of ligands with respect to their decreasing order of field strength is",o:["CO > H\u2082O > NH\u2083 > Cl\u207B","Cl\u207B > H\u2082O > NH\u2083 > CO","Cl\u207B > NH\u2083 > H\u2082O > CO","CO > NH\u2083 > H\u2082O > Cl\u207B"],c:3,s:"From the spectrochemical series, the decreasing order of field strength is CO > NH\u2083 > H\u2082O > Cl\u207B."},{id:"neet-2026r-q054",pn:54,y:"Re-NEET 2026 \xB7 21 Jun",tp:"Coordination Compounds",st:"Optical isomerism in complexes",q:`Given below are two statements:
Statement-I: [Fe(ox)\u2083]\xB3\u207B is chiral.
Statement-II: trans\u2013[Cr(H\u2082O)\u2082(ox)\u2082]\u207B is chiral.
(Given : oxH\u2082 = HOOC \u2013 COOH)
In light of the above statements, choose the most appropriate answer from the options given below:`,o:["Both Statement-I and Statement-II are incorrect","Statement-I is correct but Statement-II is incorrect","Statement-I is incorrect but Statement-II is correct","Both Statement-I and Statement-II are correct"],c:1,s:`[Fe(ox)\u2083]\xB3\u207B has two non-superimposable mirror images, so it is optically active and chiral. Statement-I is correct.
trans-[Cr(H\u2082O)\u2082(ox)\u2082]\u207B has a plane of symmetry.
So it is not chiral and is optically inactive. Statement-II is incorrect.`,sfig:{w:270,h:212,alt:"Top: [Fe(ox)\u2083]\xB3\u207B and its mirror image on either side of a mirror (three ox chelates around Fe, charge 3\u2013). Bottom: trans-[Cr(H\u2082O)\u2082(ox)\u2082]\u207B with H\u2082O above and below Cr and an ox chelate on each side.",d:[["t",60,54,"Fe","m"],["l",60,38,60,28],["l",60,28,51.8,25.8],["l",49.6,44,40.9,39],["l",40.9,39,43.2,30.8],["t",45,28,"ox","ms"],["l",60,62,60,72],["l",60,72,51.8,74.2],["l",49.6,56,40.9,61],["l",40.9,61,43.2,69.2],["t",45,80,"ox","ms"],["l",70.4,44,79.1,39],["l",79.1,39,85.1,45],["l",70.4,56,79.1,61],["l",79.1,61,85.1,55],["t",90,54,"ox","ms"],["p","M23 12 H18 V88 H23"],["p","M99 12 H104 V88 H99"],["t",106,20,"3\u2013","s"],["l",130,10,130,90],["l",130,16,136,11],["l",130,22,136,17],["l",130,28,136,23],["l",130,34,136,29],["l",130,40,136,35],["l",130,46,136,41],["l",130,52,136,47],["l",130,58,136,53],["l",130,64,136,59],["l",130,70,136,65],["l",130,76,136,71],["l",130,82,136,77],["l",130,88,136,83],["t",200,54,"Fe","m"],["l",200,38,200,28],["l",200,28,208.2,25.8],["l",210.4,44,219.1,39],["l",219.1,39,216.8,30.8],["t",215,28,"ox","ms"],["l",200,62,200,72],["l",200,72,208.2,74.2],["l",210.4,56,219.1,61],["l",219.1,61,216.8,69.2],["t",215,80,"ox","ms"],["l",189.6,44,180.9,39],["l",180.9,39,174.9,45],["l",189.6,56,180.9,61],["l",180.9,61,174.9,55],["t",170,54,"ox","ms"],["p","M161 12 H156 V88 H161"],["p","M237 12 H242 V88 H237"],["t",244,20,"3\u2013","s"],["t",130,164,"Cr","m"],["l",130,151,130,134],["t",130,130,"H\u2082O","m"],["l",130,169,130,186],["t",130,200,"H\u2082O","m"],["l",119.6,154,110.9,149],["l",110.9,149,104.9,155.1],["l",119.6,166,110.9,171],["l",110.9,171,104.9,164.9],["t",100,164,"ox","ms"],["l",140.4,154,149.1,149],["l",149.1,149,155.1,155.1],["l",140.4,166,149.1,171],["l",149.1,171,155.1,164.9],["t",160,164,"ox","ms"],["p","M93 116 H88 V204 H93"],["p","M167 116 H172 V204 H167"],["t",174,124,"\u2013","s"]]}},{id:"neet-2026r-q071",pn:71,y:"Re-NEET 2026 \xB7 21 Jun",tp:"Coordination Compounds",st:"Magnetic moment of complexes",q:`Among the species given below, the spin-only magnetic moment is highest for
(Given: Atomic number of Ti = 22, Mn = 25, Fe = 26 and Co = 27)`,o:["[Fe(CN)\u2086]\xB3\u207B","[Co(NH\u2083)\u2086]\xB3\u207A","[Ti(H\u2082O)\u2086]\xB3\u207A","[Mn(CN)\u2086]\xB3\u207B"],c:3,s:`Spin-only magnetic moment is highest when the number of unpaired electrons is highest.
[Ti(H\u2082O)\u2086]\xB3\u207A: Ti\xB3\u207A = [Ar] 4s\u2070 3d\xB9, so unpaired electrons = 1.
[Mn(CN)\u2086]\xB3\u207B: Mn\xB3\u207A = [Ar] 4s\u2070 3d\u2074, CN\u207B is a strong ligand so the 4 electrons go into t\u2082g (2 paired, 2 unpaired), so unpaired electrons = 2.
[Fe(CN)\u2086]\xB3\u207B: Fe\xB3\u207A = [Ar] 4s\u2070 3d\u2075, low spin t\u2082g\u2075, so unpaired electrons = 1.
Highest is [Mn(CN)\u2086]\xB3\u207B with 2 unpaired electrons.
Note: the printed solution figure shows only four unpaired electrons for Fe\xB3\u207A (3d\u2075); a d\u2075 ion has five, so the figure here shows five.
Note: Publisher's solution does not show Co\xB3\u207A (0 unpaired electrons, low spin d\u2076); answer unaffected.`,sfig:{w:250,h:190,alt:"Crystal field splitting with strong-field CN\u207B: singly filled d boxes (four for Mn\xB3\u207A, five for Fe\xB3\u207A) split into empty eg and lower t\u2082g; for Mn\xB3\u207A the t\u2082g boxes hold paired, single, single electrons; for Fe\xB3\u207A they hold paired, paired, single.",d:[["t",10,14,"Mn\xB3\u207A (3d\u2074)","s"],["r",10,36,14,18,""],["p","M17 51L17 39L14 43",""],["r",27,36,14,18,""],["p","M34 51L34 39L31 43",""],["r",44,36,14,18,""],["p","M51 51L51 39L48 43",""],["r",61,36,14,18,""],["p","M68 51L68 39L65 43",""],["l",75,45,85,45,""],["l",85,45,105,18,""],["l",105,18,190,18,""],["t",194,16,"eg","s"],["l",85,45,109,74,""],["l",109,74,170,74,""],["r",170,65,14,18,""],["p","M175 80L175 68L172 72",""],["p","M179 68L179 80L182 76",""],["r",187,65,14,18,""],["p","M194 80L194 68L191 72",""],["r",204,65,14,18,""],["p","M211 80L211 68L208 72",""],["t",224,82,"t\u2082g","s"],["t",10,109,"Fe\xB3\u207A (3d\u2075)","s"],["r",10,131,14,18,""],["p","M17 146L17 134L14 138",""],["r",27,131,14,18,""],["p","M34 146L34 134L31 138",""],["r",44,131,14,18,""],["p","M51 146L51 134L48 138",""],["r",61,131,14,18,""],["p","M68 146L68 134L65 138",""],["r",78,131,14,18,""],["p","M85 146L85 134L82 138",""],["l",92,140,102,140,""],["l",102,140,122,113,""],["l",122,113,190,113,""],["t",194,111,"eg","s"],["l",102,140,126,169,""],["l",126,169,170,169,""],["r",170,160,14,18,""],["p","M175 175L175 163L172 167",""],["p","M179 163L179 175L182 171",""],["r",187,160,14,18,""],["p","M192 175L192 163L189 167",""],["p","M196 163L196 175L199 171",""],["r",204,160,14,18,""],["p","M211 175L211 163L208 167",""],["t",224,177,"t\u2082g","s"]]}},{id:"neet-2026r-q072",pn:72,y:"Re-NEET 2026 \xB7 21 Jun",tp:"Coordination Compounds",st:"Isomerism in coordination compounds",q:`The complex which has facial and meridional isomers is
(Given : py = pyridine and en = H\u2082N \u2013 CH\u2082 \u2013 CH\u2082 \u2013 NH\u2082)`,o:["[Cr(H\u2082O)\u2086]\xB3\u207A","[Co(NH\u2083)\u2084(H\u2082O)\u2082]\xB3\u207A","[Ni(en)\u2082(H\u2082O)\u2082]\xB2\u207A","[Cr(py)\u2083(Cl)\u2083]"],c:3,s:`Complexes of the type [Ma\u2083b\u2083] show facial and meridional isomers.
So [Cr(py)\u2083(Cl)\u2083] shows fac and mer isomers.`},{id:"neet-2026r-q073",pn:73,y:"Re-NEET 2026 \xB7 21 Jun",tp:"Coordination Compounds",st:"Ionisation of coordination compounds",q:"A 1 : 3 electrolyte in an aqueous solution is",o:["[CoCl(NH\u2083)\u2085]Cl\u2082","[Co(NH\u2083)\u2086]Cl\u2083","[Co(NH\u2083)\u2083(NO\u2082)\u2083]","[CoCl\u2082(NH\u2083)\u2084]Cl"],c:1,s:`[Co(NH\u2083)\u2086]Cl\u2083 in water dissociates into [Co(NH\u2083)\u2086]\xB3\u207A and 3Cl\u207B ions.
So it is a 1 : 3 electrolyte.`},{id:"neet-2026r-q078",pn:78,y:"Re-NEET 2026 \xB7 21 Jun",tp:"Coordination Compounds",st:"Nomenclature of coordination compounds",q:"The formula of tetraammineaquachloridocobalt(III) chloride is",o:["[Co(NH\u2083)\u2084]Cl\u2083 \xD7 H\u2082O","[Co(NH\u2083)\u2084(H\u2082O)Cl]Cl","[Co(NH\u2083)\u2084(H\u2082O)Cl]Cl\u2082","[Co(NH\u2083)\u2084Cl\u2082] \xD7 H\u2082O"],c:2,s:`Ligands: 4 ammine (NH\u2083), 1 aqua (H\u2082O), 1 chlorido (Cl\u207B); central metal Co\xB3\u207A.
Charge on the complex ion = +3 \u2212 1 = +2, so two Cl\u207B outside the bracket.
Formula: [Co(NH\u2083)\u2084(H\u2082O)Cl]Cl\u2082.`},{id:"neet-2026-q082",pn:82,y:"NEET 2026 \xB7 3 May",tp:"Coordination Compounds",st:"Hybridisation and shape of complexes",q:`Match List I with List II :
A. [Pt(Cl\u2082)(NH\u2083)\u2082] \u2014 I. Octahedral
B. [Co(NH\u2083)\u2086]Cl\u2083 \u2014 II. Trigonal bipyramidal
C. [NiCl\u2084]\xB2\u207B \u2014 III. Square planar
D. [Fe(CO)\u2085] \u2014 IV. Tetrahedral
Choose the correct answer from the options given below :`,o:["A-I, B-III, C-IV, D-II","A-III, B-IV, C-I, D-II","A-IV, B-I, C-III, D-II","A-III, B-I, C-IV, D-II"],c:3,s:`[Pt(Cl\u2082)(NH\u2083)\u2082]: Pt has dsp\xB2 hybridisation, so the shape is square planar (A-III).
[Co(NH\u2083)\u2086]Cl\u2083: Co has d\xB2sp\xB3 hybridisation, so the shape is octahedral (B-I).
[NiCl\u2084]\xB2\u207B: Ni has sp\xB3 hybridisation, so the shape is tetrahedral (C-IV).
[Fe(CO)\u2085]: the shape is trigonal bipyramidal (D-II).`},{id:"neet-2026-q084",pn:84,y:"NEET 2026 \xB7 3 May",tp:"Coordination Compounds",st:"Ligands and denticity",q:"Which one of the following is an ambidentate ligand?",o:["Ethylenediaminetetraacetate ion","Oxalate","Ethane-1,2-diamine","Thiocyanate"],c:3,s:`An ambidentate ligand has two different donor atoms, and either one can bond to the metal in a complex.
(1) Ethylenediaminetetraacetate ion is hexadentate.
(2) Oxalate is didentate.
(3) Ethane-1,2-diamine is didentate.
(4) Thiocyanate (SCN\u207B) is an ambidentate ligand.`},{id:"neet-2026-q090",pn:90,y:"NEET 2026 \xB7 3 May",tp:"Coordination Compounds",st:"Isomerism in complexes",q:`Match List I with List II :
A. [Pt(NH\u2083)\u2082Cl\u2082] \u2014 I. Optical
B. [Co(en)\u2083]\xB3\u207A \u2014 II. Solvate
C. [Co(NH\u2083)\u2085NO\u2082]Cl\u2082 \u2014 III. Geometrical
D. [Cr(H\u2082O)\u2086]Cl\u2083 \u2014 IV. Linkage
Choose the correct answer from the options given below :`,o:["A-III, B-I, C-II, D-IV","A-I, B-III, C-II, D-IV","A-III, B-I, C-IV, D-II","A-II, B-IV, C-III, D-I"],c:2,s:`A. [Pt(NH\u2083)\u2082Cl\u2082] has cis and trans forms, so the isomerism is geometrical.
B. [Co(en)\u2083]\xB3\u207A has non-superimposable mirror images, so it shows optical isomerism.
C. [Co(NH\u2083)\u2085NO\u2082]Cl\u2082 and [Co(NH\u2083)\u2085(ONO)]Cl\u2082 are linkage isomers.
D. [Cr(H\u2082O)\u2086]Cl\u2083 and [Cr(H\u2082O)\u2085Cl]Cl\u2082\xB7H\u2082O are solvate isomers.
So A-III, B-I, C-IV, D-II.`,sfig:{w:345,h:210,alt:"A: cis and trans square planar [Pt(NH3)2Cl2], geometrical isomers. B: two octahedral [Co(en)3]3+ structures with N\u2013N chelate arcs drawn as mirror images, optical isomers; en shown as N\u2013N.",d:[["t",2,34,"A.",""],["t",60,34,"Pt","m"],["l",52,25,38,15,""],["l",52,35,38,45,""],["l",69,25,83,15,""],["l",69,35,83,45,""],["t",30,16,"Cl","m"],["t",30,54,"Cl","m"],["t",84,15,"NH\u2083",""],["t",84,52,"NH\u2083",""],["t",130,34,"and",""],["t",220,34,"Pt","m"],["l",212,25,198,15,""],["l",212,35,198,45,""],["l",229,25,243,15,""],["l",229,35,243,45,""],["t",190,16,"Cl","m"],["t",190,54,"NH\u2083","m"],["t",244,15,"NH\u2083",""],["t",244,52,"Cl",""],["t",26,72,"\u21D2 Geometrical isomers",""],["t",2,152,"B.",""],["t",72,156,"Co","m"],["t",72,112,"N","ms"],["l",72,140.1,72,120.3,""],["t",72,200,"N","ms"],["l",72,163.9,72,183.7,""],["t",36,132,"N","ms"],["l",62.3,145.5,46.1,134.7,""],["t",108,132,"N","ms"],["l",81.7,145.5,97.9,134.7,""],["t",36,180,"N","ms"],["l",62.3,158.5,46.1,169.3,""],["t",108,180,"N","ms"],["l",81.7,158.5,97.9,169.3,""],["p","M76 102Q112 96 112 122",""],["p","M32 128Q14 152 32 176",""],["p","M76 202Q112 208 112 182",""],["t",58,92,"trans","s"],["l",102,96,112,96,""],["l",112,96,112,116,""],["t",114,100,"3+","s"],["l",134,100,134,200,"d"],["t",196,156,"Co","m"],["t",196,112,"N","ms"],["l",196,140.1,196,120.3,""],["t",196,200,"N","ms"],["l",196,163.9,196,183.7,""],["t",160,132,"N","ms"],["l",186.3,145.5,170.1,134.7,""],["t",232,132,"N","ms"],["l",205.7,145.5,221.9,134.7,""],["t",160,180,"N","ms"],["l",186.3,158.5,170.1,169.3,""],["t",232,180,"N","ms"],["l",205.7,158.5,221.9,169.3,""],["p","M156 122Q156 96 192 102",""],["p","M236 128Q254 152 236 176",""],["p","M156 182Q156 208 192 202",""],["t",182,92,"cis","s"],["l",226,96,236,96,""],["l",236,96,236,116,""],["t",238,100,"3+","s"],["t",246,156,"\u21D2 Optical isomers","s"],["l",262,96,258,96,""],["l",258,96,258,118,""],["l",258,118,262,118,""],["t",272,115,"N","ms"],["p","M274 100Q284 90 294 100",""],["t",296,115,"N","ms"],["t",306,111,"= en","s"],["l",334,96,338,96,""],["l",338,96,338,118,""],["l",338,118,334,118,""]]}},{id:"neet-2025-q051",pn:51,y:"NEET 2025",tp:"Coordination Compounds",st:"Magnetic behaviour of complexes",q:`Which of the following are paramagnetic?
A. [NiCl\u2084]\xB2\u207B
B. Ni(CO)\u2084
C. [Ni(CN)\u2084]\xB2\u207B
D. [Ni(H\u2082O)\u2086]\xB2\u207A
E. Ni(PPh\u2083)\u2084
Choose the correct answer from the options given below :`,o:["A and C only","B and E only","A and D only","A, D and E only"],c:2,s:`A. [NiCl\u2084]\xB2\u207B: Ni\xB2\u207A, 3d\u2078, sp\xB3 hybridisation, 2 unpaired electrons, paramagnetic.
B. Ni(CO)\u2084: Ni, 3d\u20784s\xB2, sp\xB3, zero unpaired electrons, diamagnetic.
C. [Ni(CN)\u2084]\xB2\u207B: Ni\xB2\u207A, 3d\u2078, dsp\xB2, zero unpaired electrons, diamagnetic.
D. [Ni(H\u2082O)\u2086]\xB2\u207A: Ni\xB2\u207A, 3d\u2078, sp\xB3d\xB2, two unpaired electrons, paramagnetic.
E. Ni(PPh\u2083)\u2084: Ni, 3d\u20784s\xB2, sp\xB3, zero unpaired electrons, diamagnetic.
So A and D are paramagnetic.`},{id:"neet-2025-q057",pn:57,y:"NEET 2025",tp:"Coordination Compounds",st:"Crystal field splitting and colour",q:`The correct order of the wavelength of light absorbed by the following complexes is,
A. [Co(NH\u2083)\u2086]\xB3\u207A
B. [Co(CN)\u2086]\xB3\u207B
C. [Cu(H\u2082O)\u2084]\xB2\u207A
D. [Ti(H\u2082O)\u2086]\xB3\u207A
Choose the correct answer from the options given below:`,o:["B < D < A < C","B < A < D < C","C < D < A < B","C < A < D < B"],c:1,s:`\u03BB \u221D 1/(strength of ligand), so \u03BB \u221D 1/splitting.
A. [Co(NH\u2083)\u2086]\xB3\u207A: 475 nm.
B. [Co(CN)\u2086]\xB3\u207B: 310 nm.
C. [Cu(H\u2082O)\u2084]\xB2\u207A: 600 nm.
D. [Ti(H\u2082O)\u2086]\xB3\u207A: 498 nm.
Order of \u03BB = C > D > A > B.`},{id:"neet-2025-q063",pn:63,y:"NEET 2025",tp:"Coordination Compounds",st:"Conductance of complexes",q:"Out of the following complex compounds, which of the compound will be having the minimum conductance in solution?",o:["[Co(NH\u2083)\u2083Cl\u2083]","[Co(NH\u2083)\u2084Cl\u2082]","[Co(NH\u2083)\u2086]Cl\u2083","[Co(NH\u2083)\u2085Cl]Cl"],a:"Answer (1, 2)",s:`Conductance depends on the number of ions produced by the complex.
If the number of ions is the same, check the charge on the complex unit.
(1) [Co\u207A\xB3(NH\u2083)\u2083Cl\u2083] and (2) [Co\u207A\xB2(NH\u2083)\u2084Cl\u2082]: both complex units have no charge, so both have the same (minimum) conductance.
(3) [Co(NH\u2083)\u2086]Cl\u2083 \u2192 [Co(NH\u2083)\u2086]\u207A\xB3 + 3Cl\u207B.
(4) [Co(NH\u2083)\u2085Cl]Cl \u2192 [Co(NH\u2083)\u2085Cl]\u207A + Cl\u207B.
Note: Printed answer lists two options, 1 and 2 (both non-ionic); no single index`},{id:"neet-2024-q064",pn:64,y:"NEET 2024 \xB7 5 May",tp:"Coordination Compounds",st:"Magnetic behaviour and hybridisation of complexes",q:`Given below are two statements :
Statement-I : Both [Co(NH\u2083)\u2086]\xB3\u207A and [CoF\u2086]\xB3\u207B complexes are octahedral but differ in their magnetic behaviour.
Statement-II : [Co(NH\u2083)\u2086]\xB3\u207A is diamagnetic whereas [CoF\u2086]\xB3\u207B is paramagnetic.
In the light of the above statements, choose the correct answer from the options given below :`,o:["Statement I true but Statement II is false.","Statement I is false but Statement II is true.","Both Statement I and Statement II are true.","Both Statement I and Statement II are false."],c:2,s:`In [Co(NH\u2083)\u2086]\xB3\u207A, Co\xB3\u207A is 3d\u2076.
NH\u2083 is a strong field ligand, so the electrons pair up in 3d.
Two 3d orbitals, the 4s and three 4p orbitals form d\xB2sp\xB3 hybrids, so the complex is octahedral and diamagnetic.
In [CoF\u2086]\xB3\u207B, Co\xB3\u207A is also 3d\u2076.
F\u207B is a weak field ligand, so no pairing occurs.
The complex is sp\xB3d\xB2 hybridised (using 4s, 4p, 4d), octahedral, with four unpaired electrons, so it is paramagnetic.
Both statements are true.`,sfig:{w:380,h:216,alt:"Orbital box diagrams of Co3+ with NH3 (d2sp3, all paired) and with F- (sp3d2, four unpaired electrons)",d:[["t",6,14,"Co\xB3\u207A (free ion)","s"],["t",130,14,"3d\u2076","s"],["t",62.5,55,"3d","ms"],["r",10,22,21,21,""],["t",20.5,35.5,"\u2191\u2193","ms"],["r",31,22,21,21,""],["t",41.5,35.5,"\u2191","ms"],["r",52,22,21,21,""],["t",62.5,35.5,"\u2191","ms"],["r",73,22,21,21,""],["t",83.5,35.5,"\u2191","ms"],["r",94,22,21,21,""],["t",104.5,35.5,"\u2191","ms"],["t",137.5,55,"4s","ms"],["r",127,22,21,21,""],["t",191.5,55,"4p","ms"],["r",160,22,21,21,""],["r",181,22,21,21,""],["r",202,22,21,21,""],["t",6,80,"[Co(NH\u2083)\u2086]\xB3\u207A","s"],["t",130,80,"d\xB2sp\xB3: diamagnetic","s"],["t",62.5,121,"3d","ms"],["r",10,88,21,21,""],["t",20.5,101.5,"\u2191\u2193","ms"],["r",31,88,21,21,""],["t",41.5,101.5,"\u2191\u2193","ms"],["r",52,88,21,21,""],["t",62.5,101.5,"\u2191\u2193","ms"],["r",73,88,21,21,""],["t",83.5,101.5,"\xD7\xD7","ms"],["r",94,88,21,21,""],["t",104.5,101.5,"\xD7\xD7","ms"],["t",137.5,121,"4s","ms"],["r",127,88,21,21,""],["t",137.5,101.5,"\xD7\xD7","ms"],["t",191.5,121,"4p","ms"],["r",160,88,21,21,""],["t",170.5,101.5,"\xD7\xD7","ms"],["r",181,88,21,21,""],["t",191.5,101.5,"\xD7\xD7","ms"],["r",202,88,21,21,""],["t",212.5,101.5,"\xD7\xD7","ms"],["t",6,146,"[CoF\u2086]\xB3\u207B","s"],["t",130,146,"sp\xB3d\xB2: 4 unpaired e\u207B","s"],["t",62.5,187,"3d","ms"],["r",10,154,21,21,""],["t",20.5,167.5,"\u2191\u2193","ms"],["r",31,154,21,21,""],["t",41.5,167.5,"\u2191","ms"],["r",52,154,21,21,""],["t",62.5,167.5,"\u2191","ms"],["r",73,154,21,21,""],["t",83.5,167.5,"\u2191","ms"],["r",94,154,21,21,""],["t",104.5,167.5,"\u2191","ms"],["t",137.5,187,"4s","ms"],["r",127,154,21,21,""],["t",137.5,167.5,"\xD7\xD7","ms"],["t",191.5,187,"4p","ms"],["r",160,154,21,21,""],["t",170.5,167.5,"\xD7\xD7","ms"],["r",181,154,21,21,""],["t",191.5,167.5,"\xD7\xD7","ms"],["r",202,154,21,21,""],["t",212.5,167.5,"\xD7\xD7","ms"],["t",287.5,187,"4d","ms"],["r",235,154,21,21,""],["t",245.5,167.5,"\xD7\xD7","ms"],["r",256,154,21,21,""],["t",266.5,167.5,"\xD7\xD7","ms"],["t",6,206,"\xD7\xD7 = electron pair donated by a ligand","s"],["r",277,154,21,21,""],["r",298,154,21,21,""],["r",319,154,21,21,""]]}},{id:"neet-2024-q080",pn:80,y:"NEET 2024 \xB7 5 May",tp:"Coordination Compounds",st:"Isomerism in coordination compounds",q:`Match List-I with List-II.
List-I (Complex) \u2014 List-II (Type of isomerism)
A. [Co(NH\u2083)\u2085(NO\u2082)]Cl\u2082 \u2014 I. Solvate isomerism
B. [Co(NH\u2083)\u2085(SO\u2084)]Br \u2014 II. Linkage isomerism
C. [Co(NH\u2083)\u2086][Cr(CN)\u2086] \u2014 III. Ionization isomerism
D. [Co(H\u2082O)\u2086]Cl\u2083 \u2014 IV. Coordination isomerism
Choose the correct answer from the option given below :`,o:["A-I, B-IV, C-III, D-II","A-II, B-IV, C-III, D-I","A-II, B-III, C-IV, D-I","A-I, B-III, C-IV, D-II"],c:2,s:`A: [Co(NH\u2083)\u2085(NO\u2082)]Cl\u2082 shows linkage isomerism, since NO\u2082 can bind through N or through O. So A-II.
B: [Co(NH\u2083)\u2085(SO\u2084)]Br shows ionization isomerism. So B-III.
C: [Co(NH\u2083)\u2086][Cr(CN)\u2086] shows coordination isomerism. So C-IV.
D: [Co(H\u2082O)\u2086]Cl\u2083 shows solvate (hydrate) isomerism. So D-I.`},{id:"neet-2024-q090",pn:90,y:"NEET 2024 \xB7 5 May",tp:"Coordination Compounds",st:"Homoleptic and heteroleptic complexes",q:`Given below are two statements:
Statement-I : [Co(NH\u2083)\u2086]\xB3\u207A is a homoleptic complex whereas [Co(NH\u2083)\u2084Cl\u2082]\u207A is a heteroleptic complex.
Statement-II : Complex [Co(NH\u2083)\u2086]\xB3\u207A has only one kind of ligands but [Co(NH\u2083)\u2084Cl\u2082]\u207A has more than one kind of ligands.
In the light of the above statements, choose the correct answer from the options given below :`,o:["Statement I true but Statement II is false.","Statement I is false but Statement II is true.","Both Statement I and Statement II are true.","Both Statement I and Statement II are false."],c:2,s:`[Co(NH\u2083)\u2086]\xB3\u207A has only one type of ligand (NH\u2083) on Co\xB3\u207A, so it is homoleptic.
[Co(NH\u2083)\u2084Cl\u2082]\u207A has more than one type of ligand on Co\xB3\u207A, namely NH\u2083 and Cl\u207B, so it is heteroleptic.
Both statements are true.`},{id:"neet-2023-q085",pn:85,y:"NEET 2023 \xB7 7 May",tp:"Coordination Compounds",st:"Homoleptic and heteroleptic complexes",q:"Homoleptic complex from the following complexes is :",o:["Triamminetriaquachromium (III) chloride","Potassium trioxalatoaluminate (III)","Diamminechloridonitrito-N-platinum (II)","Pentaamminecarbonatocobalt (III) chloride"],c:1,s:`A homoleptic complex has the metal bound to only one kind of donor group.
Potassium trioxalatoaluminate (III), K\u2083[Al(ox)\u2083], has only oxalate ligands.
So it is homoleptic.`},{id:"neet-2023-q090",pn:90,y:"NEET 2023 \xB7 7 May",tp:"Coordination Compounds",st:"Chelate effect",q:"Which complex compound is most stable?",o:["[Co(NH\u2083)\u2086]\u2082(SO\u2084)\u2083","[Co(NH\u2083)\u2084(H\u2082O)Br](NO\u2083)\u2082","[Co(NH\u2083)\u2083(NO\u2083)\u2083]","[CoCl\u2082(en)\u2082]NO\u2083"],c:3,s:`Chelating ligands usually form more stable complexes than similar monodentate ligands.
Only [CoCl\u2082(en)\u2082]NO\u2083 contains a chelating ligand (en).
So it is the most stable.`},{id:"neet-2022r-q065",pn:65,y:"Re-NEET 2022 \xB7 4 Sep",tp:"Coordination Compounds",st:"Isomerism in complexes",q:`Match List - I with List - II :
List-I (Complexes): (a) [Co(NH\u2083)\u2085NO\u2082]Cl\u2082 and [Co(NH\u2083)\u2085ONO]Cl\u2082 (b) [Cr(NH\u2083)\u2086][Co(CN)\u2086] and [Cr(CN)\u2086][Co(NH\u2083)\u2086] (c) [Co(NH\u2083)\u2085(SO\u2084)]Br and [Co(NH\u2083)\u2085Br]SO\u2084 (d) [Cr(H\u2082O)\u2086]Cl\u2083 and [Cr(H\u2082O)\u2085Cl]Cl\u2082\xB7H\u2082O
List-II (Types): (i) ionisation isomerism (ii) coordination isomerism (iii) linkage isomerism (iv) solvate isomerism
Choose the correct answer from the options given below :`,o:["(a) - (iv), (b) - (iii), (c) - (ii), (d) - (i)","(a) - (iii), (b) - (i), (c) - (ii), (d) - (iv)","(a) - (ii), (b) - (iii), (c) - (iv), (d) - (i)","(a) - (iii), (b) - (ii), (c) - (i), (d) - (iv)"],c:3,s:`(a) NO\u2082 and ONO are two ways an ambidentate ligand can bind, so it is linkage isomerism.
(b) Ligands are exchanged between the cationic and anionic complex, so it is coordination isomerism.
(c) SO\u2084\xB2\u207B and Br\u207B swap between inside and outside the sphere, giving different ions in solution, so it is ionisation isomerism.
(d) The number of water molecules as ligand and as water of crystallisation differs, so it is solvate isomerism.`},{id:"neet-2022-q066",pn:66,y:"NEET 2022 \xB7 17 Jul",tp:"Coordination Compounds",st:"IUPAC naming of complexes",q:"The IUPAC name of the complex- [Ag(H\u2082O)\u2082][Ag(CN)\u2082] is:",o:["diaquasilver(II) dicyanidoargentate(II)","dicyanidosilver(I) diaquaargentate(I)","diaquasilver(I) dicyanidoargentate(I)","dicyanidosilver(II) diaquaargentate(II)"],c:2,s:`The cation is [Ag(H\u2082O)\u2082]\u207A: two water ligands, silver in +1 state, named diaquasilver(I).
The anion is [Ag(CN)\u2082]\u207B: two cyanide ligands, named dicyanidoargentate(I).
The name is diaquasilver(I) dicyanidoargentate(I).`},{id:"neet-2022-q086",pn:86,y:"NEET 2022 \xB7 17 Jul",tp:"Coordination Compounds",st:"Crystal field theory and colour",q:`The order of energy absorbed which is responsible for the color of complexes
(A) [Ni(H\u2082O)\u2082(en)\u2082]\xB2\u207A
(B) [Ni(H\u2082O)\u2084(en)]\xB2\u207A and
(C) [Ni(en)\u2083]\xB2\u207A
is`,o:["(C) > (B) > (A)","(C) > (A) > (B)","(B) > (A) > (C)","(A) > (B) > (C)"],c:1,s:`A stronger ligand field gives a larger splitting, so more energy is absorbed.
In the spectrochemical series 'en' is stronger than H\u2082O.
More 'en' ligands means higher energy absorbed.
Order: [Ni(en)\u2083]\xB2\u207A > [Ni(H\u2082O)\u2082(en)\u2082]\xB2\u207A > [Ni(H\u2082O)\u2084(en)]\xB2\u207A, i.e. (C) > (A) > (B).`},{id:"neet-2022r-q086",pn:86,y:"Re-NEET 2022 \xB7 4 Sep",tp:"Coordination Compounds",st:"Metal carbonyl bonding",q:`Given below are two statements: one is labelled as Assertion (A) and the other is labelled as Reason (R).
Assertion (A) : The metal carbon bond in metal carbonyls possesses both \u03C3 and \u03C0 character.
Reason (R) : The ligand to metal bond is a \u03C0 bond and metal to ligand bond is a \u03C3 bond.
In the Light of the above statements, choose the most appropriate answer from the options given below:`,o:["(A) is not correct but (R) is correct","Both (A) and (R) are correct and (R) is the correct explanation of (A)","Both (A) and (R) are correct but (R) is not the correct explanation of (A)","(A) is correct but (R) is not correct"],c:3,s:`In metal carbonyls the M-C bond has both \u03C3 and \u03C0 character, so (A) is correct.
The \u03C3 bond forms when the ligand donates a lone pair to the metal.
The \u03C0 bond forms when the metal donates d electrons back to the ligand's empty \u03C0* orbital (back bonding).
The reason has these two reversed, so (R) is not correct.
Note: The printed solution calls (R) correct but the printed key is 4 (R not correct); the key is kept and the solution here follows the key, since ligand to metal is the \u03C3 bond.`},{id:"neet-2021-q077",pn:77,y:"NEET 2021 \xB7 12 Sep",tp:"Coordination Compounds",st:"EDTA ligand",q:"Ethylene diaminetetraacetate (EDTA) ion is :",o:['Tridentate ligand with three "N" donor atoms','Hexadentate ligand with four "O" and two "N" donor atoms',"Unidentate ligand",'Bidentate ligand with two "N" donor atoms'],c:1,s:`EDTA\u2074\u207B has two N atoms (amine) and four carboxylate O\u207B atoms.
All six can donate a lone pair to the metal, so it is hexadentate with 4 O and 2 N donors.`,sfig:{w:300,h:235,alt:"EDTA ion bound to a metal M: two nitrogen atoms joined by a CH2-CH2 bridge, each carrying two CH2COO- arms, with arrows from the four O- atoms and the two N atoms pointing to M",d:[["t",95,64,"O\u207B","m"],["l",95,69,95,91],["t",95,104,"C","m"],["l",86,98.5,73,98.5],["l",86,101.5,73,101.5],["t",64,104,"O","m"],["t",48,92,"O\u207B","m"],["l",48,97,48,109],["t",48,122,"C","m"],["l",39,116.5,26,116.5],["l",39,119.5,26,119.5],["t",17,122,"O","m"],["l",95,109,95,130],["t",95,146,"CH\u2082","m"],["l",95,152,95,166],["t",95,178,"N","m"],["l",48,127,48,160],["t",48,174,"CH\u2082","m"],["l",63,174,86,178],["l",92,186,109,203],["l",99,168,139,84,"a"],["p","M103 61 Q125 44 138 66","a"],["p","M56 86 C78 20 140 20 138 63","a"],["t",205,64,"O\u207B","m"],["l",205,69,205,91],["t",205,104,"C","m"],["l",214,98.5,227,98.5],["l",214,101.5,227,101.5],["t",236,104,"O","m"],["t",252,92,"O\u207B","m"],["l",252,97,252,109],["t",252,122,"C","m"],["l",261,116.5,274,116.5],["l",261,119.5,274,119.5],["t",283,122,"O","m"],["l",205,109,205,130],["t",205,146,"CH\u2082","m"],["l",205,152,205,166],["t",205,178,"N","m"],["l",252,127,252,160],["t",252,174,"CH\u2082","m"],["l",237,174,214,178],["l",208,186,191,203],["l",201,168,161,84,"a"],["p","M197 61 Q175 44 162 66","a"],["p","M244 86 C222 20 160 20 162 63","a"],["t",150,72,"M","m"],["t",150,216,"CH\u2082\u2013CH\u2082","m"]]}},{id:"neet-2021-q087",pn:87,y:"NEET 2021 \xB7 12 Sep",tp:"Coordination Compounds",st:"Magnetic moment of complexes",q:`Match List-I with List-II.
List-I: (a) [Fe(CN)\u2086]\xB3\u207B (b) [Fe(H\u2082O)\u2086]\xB3\u207A (c) [Fe(CN)\u2086]\u2074\u207B (d) [Fe(H\u2082O)\u2086]\xB2\u207A
List-II: (i) 5.92 BM (ii) 0 BM (iii) 4.90 BM (iv) 1.73 BM`,o:["(a)-(iv), (b)-(i), (c)-(ii), (d)-(iii)","(a)-(iv), (b)-(ii), (c)-(i), (d)-(iii)","(a)-(ii), (b)-(iv), (c)-(iii), (d)-(i)","(a)-(i), (b)-(iii), (c)-(iv), (d)-(ii)"],c:0,s:`\u03BC = \u221A(n(n + 2)) BM, n = unpaired electrons. CN\u207B is a strong field ligand (pairs electrons); H\u2082O is weak (does not pair).
(a) Fe\xB3\u207A is d\u2075, low spin: n = 1, \u03BC = 1.73 BM.
(b) Fe\xB3\u207A d\u2075, high spin: n = 5, \u03BC = 5.92 BM.
(c) Fe\xB2\u207A d\u2076, low spin: n = 0, \u03BC = 0.
(d) Fe\xB2\u207A d\u2076, high spin: n = 4, \u03BC = 4.90 BM.
Match: a-iv, b-i, c-ii, d-iii.`},{id:"neet-2020-q146",pn:146,y:"NEET 2020 \xB7 13 Sep",tp:"Coordination Compounds",st:"Complex formation",q:"Urea reacts with water to form A which will decompose to form B. B when passed through Cu\xB2\u207A(aq), deep blue colour solution C is formed. What is the formula of C from the following ?",o:["[Cu(NH\u2083)\u2084]\xB2\u207A","Cu(OH)\u2082","CuCO\u2083.Cu(OH)\u2082","CuSO\u2084"],c:0,s:`Urea + water gives ammonium carbonate-type product A (NH\u2084OH with CO\u2082).
A decomposes on heating to give ammonia, B = NH\u2083.
Cu\xB2\u207A + 4NH\u2083 \u2192 [Cu(NH\u2083)\u2084]\xB2\u207A, which is deep blue.`},{id:"neet-2020-q174",pn:174,y:"NEET 2020 \xB7 13 Sep",tp:"Coordination Compounds",st:"Spectrochemical series",q:"Which of the following is the correct order of increasing field strength of ligands to form coordination compounds ?",o:["SCN\u207B < F\u207B < CN\u207B < C\u2082O\u2084\xB2\u207B","F\u207B < SCN\u207B < C\u2082O\u2084\xB2\u207B < CN\u207B","CN\u207B < C\u2082O\u2084\xB2\u207B < SCN\u207B < F\u207B","SCN\u207B < F\u207B < C\u2082O\u2084\xB2\u207B < CN\u207B"],c:3,s:"The spectrochemical series in increasing field strength is SCN\u207B < F\u207B < C\u2082O\u2084\xB2\u207B < CN\u207B (weak to strong)."},{id:"neet-2019-q173",pn:173,y:"NEET 2019 \xB7 5 May",tp:"Coordination Compounds",st:"Crystal field theory",q:"What is the correct electronic configuration of the central atom in K\u2084[Fe(CN)\u2086] based on crystal field theory?",o:["e\xB3t\u2082\xB3","e\u2074t\u2082\xB2","t\u2082g\u2074 e_g\xB2","t\u2082g\u2076 e_g\u2070"],c:3,s:`The complex K\u2084[Fe(CN)\u2086] has Fe\xB2\u207A with 3d\u2076.
CN\u207B is a strong field ligand, so pairing happens in the octahedral field.
All six d electrons go in the lower t\u2082g set: t\u2082g\u2076 e_g\u2070.`}]})();
